/** Retrieve the case report by id. */
export default function lookup_report(case_id: string): string {
  const reports: Record<string, string> = {"incident-00": "The checkout API is responsive. Audit logs show a token belonging to another tenant read private invoices; the CPU alarm was a stale dashboard.", "incident-01": "Users see timeouts only during traffic peaks. Workers are saturated and recover as load falls; the security scanner found no unauthorized access.", "incident-02": "Our queue depth and CPU are normal. Requests fail because the upstream tax service rejects every connection after its deployment.", "incident-03": "A cache miss raised latency, but the urgent finding is that an unauthenticated request can fetch another customer's profile.", "incident-04": "An alert mentions credentials, but the credentials are valid. The image service runs out of memory while processing larger uploads.", "incident-05": "The status page says degraded capacity, yet local workers are idle and the external payment gateway returns 503 for each charge.", "incident-06": "The public error page is stable. A leaked signing key was used to mint valid sessions from an unfamiliar network.", "incident-07": "The database is healthy and authorization checks pass. Disk space reaches zero whenever the batch importer starts.", "incident-08": "Retrying locally changes nothing: the identity provider has stopped issuing tokens, although our authentication code and CPU are healthy.", "incident-09": "The burst of requests resembles load trouble, but sampled requests are reading files outside the requesting account's scope.", "incident-10": "The vendor outage is an old resolved ticket. Current requests queue behind exhausted connection pool slots in our own service.", "incident-11": "A security test failed in staging only. Production failures began when the DNS provider stopped resolving the partner endpoint."};
  return reports[case_id];
}

