/** Retrieve the independent investigation note for this case. */
export default function lookup_context(case_id: string): string {
  const notes: Record<string, string> = {"rollout-00": "The new parser is the only canary change. Replaying the old request through it reproduces the errors; reverting it stops them.", "rollout-01": "All release gates passed. A headline incident is from yesterday's retired build and has no current requests.", "rollout-02": "The provider outage affected canary and control equally; the canary's changed path passed its checks.", "rollout-03": "A new failure is visible, but the trace IDs were lost and no one can yet attribute it to this release or the upstream.", "rollout-04": "Canary traffic exercises the changed path, required checks passed, and there is no unresolved defect report.", "rollout-05": "Metrics are steady, but the mandatory backup snapshot has not completed. This gate must precede wider rollout.", "rollout-06": "Only canary nodes use the new authorization check. A request to another tenant succeeds there and fails in control.", "rollout-07": "The shared database had an incident; both populations moved together and the changed canary code was not on the failing path.", "rollout-08": "The canary worsened, but its traffic mix shifted to a new region at the same time. No matched comparison is available yet.", "rollout-09": "The release removes a known retry storm; replay verifies that the same request no longer loops.", "rollout-10": "The canary is healthy, but the required security sign-off is still pending and cannot be waived by good metrics.", "rollout-11": "The new serializer corrupts persisted records on canary writes. Control writes remain intact; the fault disappears with the release flag off."};
  return notes[case_id];
}

